# ============================================================
# Assignment 8: Store Sales Submission Validation
#
# 13_store_sales_submission_validation.py
#
# Purpose:
#   Perform a final file-level audit of the Store Sales Kaggle
#   submission files generated by:
#
#       11_store_sales_arima_submission.py
#       12_store_sales_ets_submission.py
#
# Important:
#   - This script does NOT refit any models.
#   - This script does NOT modify submission files.
#   - This script validates the actual CSV files on disk.
#   - Both submissions must match test.csv exactly by ID/order.
#
# Expected Kaggle submission format:
#
#       id,sales
#
# Expected rows:
#
#       28,512
#
# Expected ID range:
#
#       3000888 through 3029399
#
# Output artifacts:
#
#   output/tables/
#       store_sales_submission_file_audit.csv
#       store_sales_submission_id_comparison.csv
#
#   output/results/
#       store_sales_submission_validation_results.json
#
# ============================================================


from pathlib import Path
import json

import numpy as np
import pandas as pd


# ---------------------------------------------------------
# Project directories
# ---------------------------------------------------------

PROJECT_DIR = Path(__file__).resolve().parent.parent

DATA_DIR = PROJECT_DIR / "data"

STORE_DIR = (
    DATA_DIR
    / "store_sales_time_series_forecasting"
)

OUTPUT_DIR = PROJECT_DIR / "output"

TABLES_DIR = OUTPUT_DIR / "tables"
RESULTS_DIR = OUTPUT_DIR / "results"
SUBMISSIONS_DIR = OUTPUT_DIR / "submissions"

TABLES_DIR.mkdir(
    parents=True,
    exist_ok=True
)

RESULTS_DIR.mkdir(
    parents=True,
    exist_ok=True
)


# ---------------------------------------------------------
# Expected Store Sales submission structure
# ---------------------------------------------------------

EXPECTED_ROWS = 28512

EXPECTED_COLUMNS = [
    "id",
    "sales"
]

EXPECTED_FIRST_ID = 3000888

EXPECTED_LAST_ID = 3029399


# ---------------------------------------------------------
# Submission files
# ---------------------------------------------------------

SUBMISSIONS = {

    "ARIMA": (
        SUBMISSIONS_DIR
        / "store_sales_arima_submission.csv"
    ),

    "ETS": (
        SUBMISSIONS_DIR
        / "store_sales_ets_submission.csv"
    )
}


# ---------------------------------------------------------
# Output files
# ---------------------------------------------------------

AUDIT_TABLE_PATH = (
    TABLES_DIR
    / "store_sales_submission_file_audit.csv"
)

ID_COMPARISON_PATH = (
    TABLES_DIR
    / "store_sales_submission_id_comparison.csv"
)

RESULTS_PATH = (
    RESULTS_DIR
    / "store_sales_submission_validation_results.json"
)


# =========================================================
# Start
# =========================================================

print("=" * 60)
print("13_store_sales_submission_validation.py")
print("=" * 60)


# =========================================================
# Load test.csv
# =========================================================

print(
    "\nLoading Store Sales test data..."
)

test_path = STORE_DIR / "test.csv"

if not test_path.exists():

    raise FileNotFoundError(
        "Store Sales test.csv was not found:\n"
        f"{test_path}"
    )


test = pd.read_csv(
    test_path
)

print(
    "Test data shape:",
    test.shape
)

print(
    "Test columns:",
    list(test.columns)
)


# ---------------------------------------------------------
# Validate test ID column
# ---------------------------------------------------------

if "id" not in test.columns:

    raise ValueError(
        "test.csv does not contain the required 'id' column."
    )


expected_test_ids = (
    test["id"]
    .reset_index(drop=True)
)


# ---------------------------------------------------------
# Basic test-set validation
# ---------------------------------------------------------

if len(test) != EXPECTED_ROWS:

    raise ValueError(
        f"Expected test.csv to contain "
        f"{EXPECTED_ROWS} rows, found {len(test)}."
    )


if test["id"].duplicated().any():

    raise ValueError(
        "test.csv contains duplicate IDs."
    )


if int(test["id"].iloc[0]) != EXPECTED_FIRST_ID:

    raise ValueError(
        "Unexpected first test ID: "
        f"{test['id'].iloc[0]}"
    )


if int(test["id"].iloc[-1]) != EXPECTED_LAST_ID:

    raise ValueError(
        "Unexpected last test ID: "
        f"{test['id'].iloc[-1]}"
    )


# =========================================================
# Validate each submission
# =========================================================

audit_rows = []

id_comparison_rows = []

overall_success = True


for model_name, submission_path in SUBMISSIONS.items():

    print(
        "\n" + "-" * 60
    )

    print(
        f"Validating {model_name} submission..."
    )

    print(
        "File:",
        submission_path
    )


    # -----------------------------------------------------
    # File existence
    # -----------------------------------------------------

    file_exists = submission_path.exists()

    if not file_exists:

        print(
            "STATUS: FILE NOT FOUND"
        )

        audit_rows.append({

            "model":
                model_name,

            "file":
                str(submission_path),

            "file_exists":
                False,

            "rows":
                np.nan,

            "columns":
                np.nan,

            "columns_correct":
                False,

            "first_id":
                np.nan,

            "last_id":
                np.nan,

            "id_order_matches_test":
                False,

            "duplicate_ids":
                np.nan,

            "missing_sales":
                np.nan,

            "nonfinite_sales":
                np.nan,

            "negative_sales":
                np.nan,

            "sales_min":
                np.nan,

            "sales_max":
                np.nan,

            "sales_mean":
                np.nan,

            "sales_total":
                np.nan,

            "status":
                "FAIL"
        })

        overall_success = False

        continue


    # -----------------------------------------------------
    # Load submission
    # -----------------------------------------------------

    try:

        submission = pd.read_csv(
            submission_path
        )

    except Exception as exc:

        print(
            "STATUS: COULD NOT READ FILE"
        )

        print(
            "Error:",
            str(exc)
        )

        audit_rows.append({

            "model":
                model_name,

            "file":
                str(submission_path),

            "file_exists":
                True,

            "rows":
                np.nan,

            "columns":
                np.nan,

            "columns_correct":
                False,

            "first_id":
                np.nan,

            "last_id":
                np.nan,

            "id_order_matches_test":
                False,

            "duplicate_ids":
                np.nan,

            "missing_sales":
                np.nan,

            "nonfinite_sales":
                np.nan,

            "negative_sales":
                np.nan,

            "sales_min":
                np.nan,

            "sales_max":
                np.nan,

            "sales_mean":
                np.nan,

            "sales_total":
                np.nan,

            "status":
                "FAIL"
        })

        overall_success = False

        continue


    print(
        "Rows:",
        len(submission)
    )

    print(
        "Columns:",
        list(submission.columns)
    )


    # -----------------------------------------------------
    # Column validation
    # -----------------------------------------------------

    columns_correct = (
        list(submission.columns)
        == EXPECTED_COLUMNS
    )

    if not columns_correct:

        print(
            "FAIL: Submission columns do not match "
            "['id', 'sales']."
        )


    # -----------------------------------------------------
    # Row-count validation
    # -----------------------------------------------------

    rows_correct = (
        len(submission)
        == EXPECTED_ROWS
    )

    if not rows_correct:

        print(
            "FAIL: Unexpected submission row count."
        )


    # -----------------------------------------------------
    # ID validation
    # -----------------------------------------------------

    if "id" in submission.columns:

        first_id = (
            int(submission["id"].iloc[0])
            if len(submission) > 0
            else np.nan
        )

        last_id = (
            int(submission["id"].iloc[-1])
            if len(submission) > 0
            else np.nan
        )

        duplicate_ids = int(
            submission["id"]
            .duplicated()
            .sum()
        )

        id_order_matches_test = (
            len(submission)
            == len(expected_test_ids)
            and
            submission["id"]
            .reset_index(drop=True)
            .equals(
                expected_test_ids
            )
        )

    else:

        first_id = np.nan

        last_id = np.nan

        duplicate_ids = np.nan

        id_order_matches_test = False


    if duplicate_ids != 0:

        print(
            "FAIL: Duplicate IDs:",
            duplicate_ids
        )


    if not id_order_matches_test:

        print(
            "FAIL: Submission IDs do not exactly match "
            "test.csv in row order."
        )


    # -----------------------------------------------------
    # Sales validation
    # -----------------------------------------------------

    if "sales" in submission.columns:

        missing_sales = int(
            submission["sales"].isna().sum()
        )

        sales_numeric = pd.to_numeric(
            submission["sales"],
            errors="coerce"
        )

        nonfinite_sales = int(
            (
                ~np.isfinite(
                    sales_numeric.to_numpy(
                        dtype=float
                    )
                )
            ).sum()
        )

        negative_sales = int(
            (
                sales_numeric < 0
            ).sum()
        )

        sales_min = float(
            sales_numeric.min()
        )

        sales_max = float(
            sales_numeric.max()
        )

        sales_mean = float(
            sales_numeric.mean()
        )

        sales_total = float(
            sales_numeric.sum()
        )

    else:

        missing_sales = np.nan

        nonfinite_sales = np.nan

        negative_sales = np.nan

        sales_min = np.nan

        sales_max = np.nan

        sales_mean = np.nan

        sales_total = np.nan


    if missing_sales != 0:

        print(
            "FAIL: Missing sales values:",
            missing_sales
        )


    if nonfinite_sales != 0:

        print(
            "FAIL: Non-finite sales values:",
            nonfinite_sales
        )


    if negative_sales != 0:

        print(
            "FAIL: Negative sales values:",
            negative_sales
        )


    # -----------------------------------------------------
    # Overall submission status
    # -----------------------------------------------------

    submission_passed = (

        file_exists

        and rows_correct

        and columns_correct

        and id_order_matches_test

        and duplicate_ids == 0

        and missing_sales == 0

        and nonfinite_sales == 0

        and negative_sales == 0
    )


    if submission_passed:

        status = "PASS"

        print(
            "\nSTATUS: PASS"
        )

    else:

        status = "FAIL"

        overall_success = False

        print(
            "\nSTATUS: FAIL"
        )


    # -----------------------------------------------------
    # Save audit row
    # -----------------------------------------------------

    audit_rows.append({

        "model":
            model_name,

        "file":
            str(submission_path),

        "file_exists":
            file_exists,

        "rows":
            len(submission),

        "columns":
            ",".join(
                submission.columns.astype(str)
            ),

        "columns_correct":
            columns_correct,

        "first_id":
            first_id,

        "last_id":
            last_id,

        "id_order_matches_test":
            id_order_matches_test,

        "duplicate_ids":
            duplicate_ids,

        "missing_sales":
            missing_sales,

        "nonfinite_sales":
            nonfinite_sales,

        "negative_sales":
            negative_sales,

        "sales_min":
            sales_min,

        "sales_max":
            sales_max,

        "sales_mean":
            sales_mean,

        "sales_total":
            sales_total,

        "status":
            status
    })


    # -----------------------------------------------------
    # Detailed ID comparison
    #
    # Only record discrepancies so that the resulting file
    # remains compact.
    # -----------------------------------------------------

    if (
        "id" in submission.columns
        and
        len(submission)
        == len(expected_test_ids)
    ):

        submitted_ids = (
            submission["id"]
            .reset_index(drop=True)
        )

        mismatch_mask = (
            submitted_ids
            != expected_test_ids
        )

        mismatch_positions = np.where(
            mismatch_mask
        )[0]

        for position in mismatch_positions:

            id_comparison_rows.append({

                "model":
                    model_name,

                "row_number":
                    int(position + 1),

                "test_id":
                    int(
                        expected_test_ids.iloc[position]
                    ),

                "submission_id":
                    int(
                        submitted_ids.iloc[position]
                    )
            })


# =========================================================
# Save audit table
# =========================================================

audit_df = pd.DataFrame(
    audit_rows
)

audit_df.to_csv(
    AUDIT_TABLE_PATH,
    index=False
)

print(
    "\nSaved audit table:"
)

print(
    AUDIT_TABLE_PATH
)


# =========================================================
# Save ID discrepancy table
# =========================================================

id_comparison_df = pd.DataFrame(
    id_comparison_rows,
    columns=[
        "model",
        "row_number",
        "test_id",
        "submission_id"
    ]
)

id_comparison_df.to_csv(
    ID_COMPARISON_PATH,
    index=False
)

print(
    "Saved ID comparison table:"
)

print(
    ID_COMPARISON_PATH
)


# =========================================================
# Build validation results metadata
# =========================================================

passed_models = (
    audit_df[
        audit_df["status"] == "PASS"
    ]["model"]
    .tolist()
)

failed_models = (
    audit_df[
        audit_df["status"] == "FAIL"
    ]["model"]
    .tolist()
)


validation_results = {

    "project":
        "Assignment 8",

    "dataset":
        "Store Sales Time Series Forecasting",

    "validation_type":
        "Final Kaggle submission file audit",

    "model_submissions": {

        "ARIMA":
            str(
                SUBMISSIONS["ARIMA"]
            ),

        "ETS":
            str(
                SUBMISSIONS["ETS"]
            )
    },

    "expected_submission": {

        "rows":
            EXPECTED_ROWS,

        "columns":
            EXPECTED_COLUMNS,

        "first_id":
            EXPECTED_FIRST_ID,

        "last_id":
            EXPECTED_LAST_ID
    },

    "passed_models":
        passed_models,

    "failed_models":
        failed_models,

    "overall_status":
        "PASS"
        if overall_success
        else "FAIL",

    "id_discrepancy_rows":
        int(
            len(id_comparison_df)
        ),

    "file_audit": {

        model:
            {
                "status":
                    str(
                        audit_df.loc[
                            audit_df["model"] == model,
                            "status"
                        ].iloc[0]
                    ),

                "rows":
                    int(
                        audit_df.loc[
                            audit_df["model"] == model,
                            "rows"
                        ].iloc[0]
                    ),

                "first_id":
                    int(
                        audit_df.loc[
                            audit_df["model"] == model,
                            "first_id"
                        ].iloc[0]
                    ),

                "last_id":
                    int(
                        audit_df.loc[
                            audit_df["model"] == model,
                            "last_id"
                        ].iloc[0]
                    ),

                "missing_sales":
                    int(
                        audit_df.loc[
                            audit_df["model"] == model,
                            "missing_sales"
                        ].iloc[0]
                    ),

                "duplicate_ids":
                    int(
                        audit_df.loc[
                            audit_df["model"] == model,
                            "duplicate_ids"
                        ].iloc[0]
                    ),

                "negative_sales":
                    int(
                        audit_df.loc[
                            audit_df["model"] == model,
                            "negative_sales"
                        ].iloc[0]
                    )
            }

        for model in SUBMISSIONS
        if model in audit_df["model"].values
    }
}


with open(
    RESULTS_PATH,
    "w",
    encoding="utf-8"
) as results_file:

    json.dump(
        validation_results,
        results_file,
        indent=4
    )


print(
    "Saved validation metadata:"
)

print(
    RESULTS_PATH
)


# =========================================================
# Final console summary
# =========================================================

print(
    "\n" + "=" * 60
)

print(
    "FINAL STORE SALES SUBMISSION AUDIT"
)

print(
    "=" * 60
)

print(
    "\nExpected rows:",
    EXPECTED_ROWS
)

print(
    "Expected columns:",
    EXPECTED_COLUMNS
)

print(
    "Expected first ID:",
    EXPECTED_FIRST_ID
)

print(
    "Expected last ID:",
    EXPECTED_LAST_ID
)

print(
    "\nSubmission results:"
)

for model_name in SUBMISSIONS:

    matching_rows = audit_df[
        audit_df["model"] == model_name
    ]

    if matching_rows.empty:

        print(
            f"  {model_name}: NOT VALIDATED"
        )

        continue

    row = matching_rows.iloc[0]

    print(
        f"  {model_name}: {row['status']}"
    )

    print(
        f"    Rows: {row['rows']}"
    )

    print(
        f"    Columns correct: "
        f"{row['columns_correct']}"
    )

    print(
        f"    IDs match test.csv: "
        f"{row['id_order_matches_test']}"
    )

    print(
        f"    Missing sales: "
        f"{row['missing_sales']}"
    )

    print(
        f"    Duplicate IDs: "
        f"{row['duplicate_ids']}"
    )

    print(
        f"    Negative sales: "
        f"{row['negative_sales']}"
    )


print(
    "\nOverall status:",
    "PASS" if overall_success else "FAIL"
)

print(
    "ID discrepancy rows:",
    len(id_comparison_df)
)


if overall_success:

    print(
        "\nBoth Store Sales Kaggle submission files "
        "passed final file-level validation."
    )

    print(
        "\nThe files are ready for Kaggle upload."
    )

else:

    print(
        "\nOne or more Store Sales submission files "
        "failed final validation."
    )

    print(
        "\nReview the audit artifacts before uploading."
    )


print(
    "\n" + "=" * 60
)

print(
    "13_store_sales_submission_validation.py completed."
)

print(
    "=" * 60
)
